// Unit battery for QP's PERSISTENT working-set factorization (doubleQPFactorState + QP.TryAddToFactor /
// DropFromFactor / ApplyFactorQtForward / FormNullSpaceBasisFromFactor / RefactorWorkingSet) -- the
// up/downdated QR of A_Wᵀ the active-set loop carries across iterations. INTERNAL API, reached via the
// same InternalsVisibleTo route as QPActiveSetTests.double.cs; same Burst job + Fail[] pattern.
//
// The factorization invariants verified after every add/drop below (VerifyState):
//   (1) Q̂ᵀ·a_kk == R's column kk on its leading entries, ~0 below them and on the whole tail -- i.e.
//       the log-represented Q̂ and the maintained R really factor the CURRENT A_Wᵀ, column by column.
//   (2) Z from the log satisfies A_W·Z ~ 0 (null-space property) and ZᵀZ ~ I (orthonormality).
// These pin the update algebra itself (reflector replay order, Givens convention, R shifts), not just
// end-to-end solver answers.
//
// CornerToInterior is the integration case: box QP started at a fully-tight corner (k = n = 12) whose
// optimum is interior, forcing 12 consecutive drops -- more than doubleQPFactorState.DeadCap (8), so at
// least one RefactorWorkingSet fallback runs inside the loop; it also passes through k = 0 (empty
// working set) before converging.
//
// The PERSISTENT REDUCED SPACE (doubleQPReducedState + QP.RebuildReduced / UpdateReducedOnAdd /
// UpdateReducedOnDrop / FormNullSpaceColumn / SolveReducedNewtonStepCached) gets its own battery below:
//   * IncrementalReduced -- after every add/drop (run under the loop's own rebuild policy), the
//     incrementally-maintained Z / QZ / H_Z must match a fresh FormNullSpaceBasisFromFactor + Q·Z +
//     ZᵀQZ column for column (the buffers live in the log's own frame, so agreement is entrywise, not
//     just up to an orthogonal mix); covers the RebuildCap and DeadCap-refactor rebuild triggers and
//     the k = 0 (nz = n) edge.
//   * CachedRetry -- a PSD-not-PD Q whose null space overlaps span(Z) forces the regularized retry;
//     the cached H_Z must come through the failed factor byte-identical.
//   * FallbackEquivalence -- qpActiveSetCore with useIncrementalReduced true vs false on the same
//     strictly convex instances must agree on status/objective/x (VALUES, not iteration paths).
public class doubleQPFactorStateTests
{
    // ================================================================================================
    // Add / drop / re-add sequence over a mixed working set (general rows + a bound row), verifying
    // the factorization invariants after every mutation. Drops hit the middle, first, and last column
    // (the last-column drop produces no rotations -- the shift/rotation loop's empty edge).
    // ================================================================================================
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct UpDownDateJob : IJob
    {
        public NativeArray<double> Fail;

        static void BuildCol(in doubleMxN A, int m, int n, int t, WorkingSetStatus st, ref doubleN v)
        {
            double sign = st == WorkingSetStatus.ActiveUpper ? (double)(-1) : (double)1;
            if (t < m)
                for (int i = 0; i < n; i++) v[i] = sign * A[t, i];
            else
            {
                for (int i = 0; i < n; i++) v[i] = (double)0;
                v[t - m] = sign;
            }
        }

        void VerifyState(ref doubleQPFactorState s, in doubleMxN A, int m, int n,
                         NativeArray<byte> statusByT, int baseId, double tol)
        {
            int k = s.k, nz = n - k;
            var v = new doubleN(n, Allocator.Temp, false);

            // (1) Q̂ᵀ A_Wᵀ == [R; 0], column by column
            double dev = 0;
            for (int kk = 0; kk < k; kk++)
            {
                int t = s.rowOfCol[kk];
                BuildCol(in A, m, n, t, (WorkingSetStatus)statusByT[t], ref v);
                QP.ApplyFactorQtForward(ref s, ref v);
                for (int i = 0; i <= kk; i++) dev = math.max(dev, math.abs((double)(v[i] - s.R[i, kk])));
                for (int i = kk + 1; i < n; i++) dev = math.max(dev, math.abs((double)v[i]));
            }
            H.AssertLE(Fail, baseId + 0, dev, tol);

            // (2) Z: A_W Z == 0 and ZᵀZ == I
            if (nz > 0)
            {
                var Z = new doubleMxN(n, nz, Allocator.Temp, true);
                QP.FormNullSpaceBasisFromFactor(ref s, ref Z);

                double devNull = 0;
                for (int kk = 0; kk < k; kk++)
                {
                    int t = s.rowOfCol[kk];
                    BuildCol(in A, m, n, t, (WorkingSetStatus)statusByT[t], ref v);
                    for (int j = 0; j < nz; j++)
                    {
                        double acc = 0;
                        for (int i = 0; i < n; i++) acc += (double)v[i] * (double)Z[i, j];
                        devNull = math.max(devNull, math.abs(acc));
                    }
                }
                H.AssertLE(Fail, baseId + 1, devNull, tol);

                double devOrtho = 0;
                for (int a = 0; a < nz; a++)
                    for (int b = 0; b < nz; b++)
                    {
                        double acc = 0;
                        for (int i = 0; i < n; i++) acc += (double)Z[i, a] * (double)Z[i, b];
                        devOrtho = math.max(devOrtho, math.abs(acc - (a == b ? 1.0 : 0.0)));
                    }
                H.AssertLE(Fail, baseId + 2, devOrtho, tol);
                Z.Dispose();
            }
            v.Dispose();
        }

        void Add(ref doubleQPFactorState s, in doubleMxN A, int m, int n, int t, WorkingSetStatus st,
                 NativeArray<byte> statusByT, double thr, int id)
        {
            H.AssertTrue(Fail, id, QP.TryAddToFactor(in A, m, n, t, st, ref s, thr));
            statusByT[t] = (byte)st;
        }

        void Drop(ref doubleQPFactorState s, int col, NativeArray<byte> statusByT)
        {
            statusByT[s.rowOfCol[col]] = (byte)WorkingSetStatus.Inactive;
            QP.DropFromFactor(col, ref s);
        }

        public void Execute()
        {
            const int n = 6, m = 3;
            const int T = m + n;
            double tol = 1e-12;

            var A = new doubleMxN(m, n, Allocator.Temp);
            A[0, 0] = 1f; A[0, 1] = 2f; A[0, 3] = -1f; A[0, 4] = 0.5f;
            A[1, 1] = 1f; A[1, 2] = -1f; A[1, 3] = 2f; A[1, 5] = 1f;
            A[2, 0] = 3f; A[2, 2] = 1f; A[2, 4] = 2f; A[2, 5] = -1f;

            var statusByT = new NativeArray<byte>(T, Allocator.Temp);
            var s = doubleQPFactorState.Create(n);
            double thr = Consts.doubleZeroThreshold * math.max(Norms.LInf(in A), (double)1);

            // build a 3-column working set: two general rows (one upper-oriented) + one bound row
            Add(ref s, in A, m, n, 0, WorkingSetStatus.ActiveLower, statusByT, thr, 1);
            Add(ref s, in A, m, n, 1, WorkingSetStatus.ActiveUpper, statusByT, thr, 2);
            Add(ref s, in A, m, n, m + 2, WorkingSetStatus.ActiveLower, statusByT, thr, 3);
            VerifyState(ref s, in A, m, n, statusByT, 10, tol);

            // drop the MIDDLE column (one Givens rotation), then re-add a new row over the rotated log
            Drop(ref s, 1, statusByT);
            VerifyState(ref s, in A, m, n, statusByT, 20, tol);

            Add(ref s, in A, m, n, 2, WorkingSetStatus.ActiveLower, statusByT, thr, 4);
            VerifyState(ref s, in A, m, n, statusByT, 30, tol);

            // drop the FIRST column (rotation chain over every remaining column)
            Drop(ref s, 0, statusByT);
            VerifyState(ref s, in A, m, n, statusByT, 40, tol);

            // drop the LAST column (no rotations at all)
            Drop(ref s, s.k - 1, statusByT);
            H.AssertTrue(Fail, 5, s.k == 1);
            VerifyState(ref s, in A, m, n, statusByT, 50, tol);

            s.Dispose();
            statusByT.Dispose();
            A.Dispose();
        }
    }

    // ================================================================================================
    // Rank guard through the update path: a duplicated (scaled) row must be REJECTED by
    // TryAddToFactor with the state left untouched, exactly like the from-scratch trial factor it
    // replaced; an independent row must still be accepted afterwards.
    // ================================================================================================
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct DependentAddJob : IJob
    {
        public NativeArray<double> Fail;

        public void Execute()
        {
            const int n = 4, m = 3;

            var A = new doubleMxN(m, n, Allocator.Temp);
            A[0, 0] = 1f; A[0, 1] = 1f;
            A[1, 0] = 2f; A[1, 1] = 2f;   // = 2 * row 0: dependent
            A[2, 2] = 1f; A[2, 3] = 1f;

            var s = doubleQPFactorState.Create(n);
            double thr = (double)1e-10;

            H.AssertTrue(Fail, 1, QP.TryAddToFactor(in A, m, n, 0, WorkingSetStatus.ActiveLower, ref s, thr));
            int k0 = s.k, ops0 = s.opCount, refl0 = s.reflCount;

            H.AssertTrue(Fail, 2, !QP.TryAddToFactor(in A, m, n, 1, WorkingSetStatus.ActiveLower, ref s, thr));
            H.AssertTrue(Fail, 3, s.k == k0 && s.opCount == ops0 && s.reflCount == refl0);

            H.AssertTrue(Fail, 4, QP.TryAddToFactor(in A, m, n, 2, WorkingSetStatus.ActiveLower, ref s, thr));
            H.AssertTrue(Fail, 5, s.k == 2);

            s.Dispose();
            A.Dispose();
        }
    }

    // ================================================================================================
    // Integration: box QP from a fully-tight corner (k = n = 12) with an interior optimum -- 12
    // consecutive drops force the DeadCap refactor fallback inside qpActiveSetCore's loop, and
    // the working set passes through k = 0 before the final step. min 1/2 xᵀx - 2·1ᵀx, 0 <= x <= 10,
    // x0 = 0: optimum x* = 2·ones (strictly interior), objective = -2n.
    // ================================================================================================
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct CornerToInteriorJob : IJob
    {
        public NativeArray<double> Fail;

        public void Execute()
        {
            const int n = 12;

            var Q = new doubleMxN(n, n, Allocator.Temp);
            for (int i = 0; i < n; i++) Q[i, i] = 1f;
            var c = GenerateOP.doubleVec(n, (double)(-2), Allocator.Temp);
            var A = new doubleMxN(0, n, Allocator.Temp);
            var b = new doubleN(0, Allocator.Temp);
            var senses = new NativeArray<ConstraintSense>(0, Allocator.Temp);
            var xl = new doubleN(n, Allocator.Temp);                  // 0
            var xu = GenerateOP.doubleVec(n, (double)10, Allocator.Temp);
            var x = new doubleN(n, Allocator.Temp);                   // x0 = 0: every lower bound tight

            var info = QP.qpActiveSetCore(in Q, in c, in A, in b, senses, in xl, in xu, ref x, out double obj, 0);

            H.AssertTrue(Fail, 1, info.status == QPStatus.Optimal);
            H.AssertTrue(Fail, 2, info.iterations >= n);   // at least one drop per variable
            double tol = 1e-10;
            for (int i = 0; i < n; i++)
                H.AssertLE(Fail, 3, math.abs((double)x[i] - 2.0), tol);
            H.AssertLE(Fail, 4, math.abs(obj - (-2.0 * n)), tol * n);

            senses.Dispose();
        }
    }

    // ================================================================================================
    // Reduced-space maintenance: after EVERY add/drop (run under the loop's own protocol -- rebuild
    // when stale or past RebuildCap, refactor + stale at DeadCap), the persistent Z / QZ / H_Z must
    // match a fresh rebuild entrywise. The opening script pins the INCREMENTAL algebra directly (no
    // rebuild triggers fire); the churn loop then crosses both rebuild triggers and drives k to 0
    // (nz = n, the empty-working-set frame).
    // ================================================================================================
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct IncrementalReducedJob : IJob
    {
        public NativeArray<double> Fail;

        // the loop's own rebuild policy, applied before every reduced-buffer read
        static void Sync(in doubleMxN Q, ref doubleQPFactorState s, ref doubleQPReducedState red)
        {
            if (red.stale || red.changeCount >= doubleQPReducedState.RebuildCap)
                QP.RebuildReduced(in Q, ref s, ref red);
        }

        void VerifyReduced(in doubleMxN Q, ref doubleQPFactorState s, ref doubleQPReducedState red,
                           int baseId, double tol)
        {
            int n = s.n, k = s.k, nz = n - k;
            if (nz <= 0) return;

            var Zf = new doubleMxN(n, nz, Allocator.Temp, true);
            QP.FormNullSpaceBasisFromFactor(ref s, ref Zf);
            var QZf = new doubleMxN(n, nz, Allocator.Temp, true);
            Blas.dot(in Q, in Zf, ref QZf);
            var Hzf = new doubleMxN(nz, nz, Allocator.Temp, true);
            Blas.dotSym(in Zf, in QZf, ref Hzf);

            double devZ = 0, devQZ = 0, devHz = 0;
            for (int i = 0; i < n; i++)
                for (int j = 0; j < nz; j++)
                {
                    devZ = math.max(devZ, math.abs((double)(red.Z[i, j] - Zf[i, j])));
                    devQZ = math.max(devQZ, math.abs((double)(red.QZ[i, j] - QZf[i, j])));
                }
            for (int i = 0; i < nz; i++)
                for (int j = 0; j < nz; j++)
                    devHz = math.max(devHz, math.abs((double)(red.Hz[i, j] - Hzf[i, j])));

            H.AssertLE(Fail, baseId + 0, devZ, tol);
            H.AssertLE(Fail, baseId + 1, devQZ, tol);
            H.AssertLE(Fail, baseId + 2, devHz, tol);

            Hzf.Dispose(); QZf.Dispose(); Zf.Dispose();
        }

        void AddU(in doubleMxN A, int m, int n, int t, WorkingSetStatus st, NativeArray<byte> statusByT,
                  ref doubleQPFactorState s, ref doubleQPReducedState red, double thr, int id)
        {
            H.AssertTrue(Fail, id, QP.TryAddToFactor(in A, m, n, t, st, ref s, thr));
            statusByT[t] = (byte)st;
            QP.UpdateReducedOnAdd(ref s, ref red);
        }

        void DropU(in doubleMxN Q, in doubleMxN A, int m, int n, int T, int col, NativeArray<byte> statusByT,
                   ref doubleQPFactorState s, ref doubleQPReducedState red, double thr)
        {
            statusByT[s.rowOfCol[col]] = (byte)WorkingSetStatus.Inactive;
            QP.DropFromFactor(col, ref s);
            if (s.deadCount >= doubleQPFactorState.DeadCap)
            {
                QP.RefactorWorkingSet(in A, m, n, T, statusByT, ref s, thr);
                red.stale = true;
            }
            else
                QP.UpdateReducedOnDrop(in Q, ref s, ref red);
        }

        public void Execute()
        {
            const int n = 6, m = 3;
            const int T = m + n;
            double tol = 1e-11;

            var A = new doubleMxN(m, n, Allocator.Temp);
            A[0, 0] = 1f; A[0, 1] = 2f; A[0, 3] = -1f; A[0, 4] = 0.5f;
            A[1, 1] = 1f; A[1, 2] = -1f; A[1, 3] = 2f; A[1, 5] = 1f;
            A[2, 0] = 3f; A[2, 2] = 1f; A[2, 4] = 2f; A[2, 5] = -1f;

            // symmetric, diagonally dominant (PD) test Hessian
            var Q = new doubleMxN(n, n, Allocator.Temp);
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    Q[i, j] = i == j ? (double)4 : (double)1 / (double)(1 + math.abs(i - j));

            var statusByT = new NativeArray<byte>(T, Allocator.Temp);
            var s = doubleQPFactorState.Create(n);
            var red = doubleQPReducedState.Create(n);
            double thr = Consts.doubleZeroThreshold * math.max(Norms.LInf(in A), (double)1);

            // seed 3 columns while stale (mimics SeedWorkingSet), then the first-use rebuild
            AddU(in A, m, n, 0, WorkingSetStatus.ActiveLower, statusByT, ref s, ref red, thr, 1);
            AddU(in A, m, n, 1, WorkingSetStatus.ActiveUpper, statusByT, ref s, ref red, thr, 2);
            AddU(in A, m, n, m + 2, WorkingSetStatus.ActiveLower, statusByT, ref s, ref red, thr, 3);
            Sync(in Q, ref s, ref red);
            VerifyReduced(in Q, ref s, ref red, 10, tol);

            // pure-incremental phase: no rebuild trigger fires anywhere below (changeCount stays under
            // RebuildCap, deadCount under DeadCap), so every verify pins the update algebra itself
            AddU(in A, m, n, 2, WorkingSetStatus.ActiveLower, statusByT, ref s, ref red, thr, 4);
            VerifyReduced(in Q, ref s, ref red, 20, tol);

            DropU(in Q, in A, m, n, T, 1, statusByT, ref s, ref red, thr);       // middle column
            VerifyReduced(in Q, ref s, ref red, 30, tol);

            AddU(in A, m, n, m + 0, WorkingSetStatus.ActiveLower, statusByT, ref s, ref red, thr, 5);
            VerifyReduced(in Q, ref s, ref red, 40, tol);

            DropU(in Q, in A, m, n, T, 0, statusByT, ref s, ref red, thr);       // first column
            VerifyReduced(in Q, ref s, ref red, 50, tol);

            DropU(in Q, in A, m, n, T, s.k - 1, statusByT, ref s, ref red, thr); // last column (no rotations)
            VerifyReduced(in Q, ref s, ref red, 60, tol);

            while (s.k > 0)                                                       // down to the empty set
                DropU(in Q, in A, m, n, T, 0, statusByT, ref s, ref red, thr);
            H.AssertTrue(Fail, 6, s.k == 0);
            VerifyReduced(in Q, ref s, ref red, 70, tol);                         // nz = n: full-frame edge

            // churn: add/drop cycles from the empty set -- crosses RebuildCap (adds+drops both count)
            // AND DeadCap (refactor + stale), so both rebuild triggers run under the loop's policy
            for (int cycle = 0; cycle < 12; cycle++)
            {
                int t = (cycle & 1) == 0 ? 0 : m + 1;
                Sync(in Q, ref s, ref red);
                if (QP.TryAddToFactor(in A, m, n, t, WorkingSetStatus.ActiveLower, ref s, thr))
                {
                    statusByT[t] = (byte)WorkingSetStatus.ActiveLower;
                    QP.UpdateReducedOnAdd(ref s, ref red);
                }
                Sync(in Q, ref s, ref red);
                VerifyReduced(in Q, ref s, ref red, 80, tol);

                DropU(in Q, in A, m, n, T, 0, statusByT, ref s, ref red, thr);
                Sync(in Q, ref s, ref red);
                VerifyReduced(in Q, ref s, ref red, 90, tol);
            }

            red.Dispose();
            s.Dispose();
            statusByT.Dispose();
            Q.Dispose();
            A.Dispose();
        }
    }

    // ================================================================================================
    // Regularized retry off the CACHED H_Z: Q PSD but rank-deficient with null(Q) inside span(Z), so
    // the first Cholesky must break down and the retry must succeed -- with the cached H_Z coming
    // through byte-identical (the factor only ever runs on scratch).
    // ================================================================================================
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct CachedRetryJob : IJob
    {
        public NativeArray<double> Fail;

        public void Execute()
        {
            const int n = 4, m = 1;

            var A = new doubleMxN(m, n, Allocator.Temp);
            A[0, 0] = 1f; A[0, 1] = 1f; A[0, 2] = 1f; A[0, 3] = 1f;   // never added -- bound row only

            var Q = new doubleMxN(n, n, Allocator.Temp);   // PSD rank 2: null(Q) = span(e2, e3)
            Q[0, 0] = 1f; Q[1, 1] = 1f;

            var s = doubleQPFactorState.Create(n);
            var red = doubleQPReducedState.Create(n);
            double thr = Consts.doubleZeroThreshold;

            // working set = {x0 at lower}: Z spans coords 1..3, H_Z = diag(1, 0, 0) -- exactly singular
            H.AssertTrue(Fail, 1, QP.TryAddToFactor(in A, m, n, m + 0, WorkingSetStatus.ActiveLower, ref s, thr));
            QP.RebuildReduced(in Q, ref s, ref red);

            int nz = n - s.k;
            var gz = new doubleN(nz, Allocator.Temp, false);
            gz[0] = (double)1; gz[1] = (double)0.5; gz[2] = (double)(-0.25);
            var y = new doubleN(nz, Allocator.Temp, false);

            var snap = new doubleMxN(nz, nz, Allocator.Temp, true);
            for (int i = 0; i < nz; i++)
                for (int j = 0; j < nz; j++) snap[i, j] = red.Hz[i, j];

            var info = QP.SolveReducedNewtonStepCached(ref red, nz, ref gz, ref y, (double)1, out bool regularized);
            H.AssertTrue(Fail, 2, info.Solved);
            H.AssertTrue(Fail, 3, regularized);

            double devHz = 0;
            for (int i = 0; i < nz; i++)
                for (int j = 0; j < nz; j++)
                    devHz = math.max(devHz, math.abs((double)(red.Hz[i, j] - snap[i, j])));
            H.AssertLE(Fail, 4, devHz, 0.0);   // cached H_Z untouched, bit for bit

            double gp = 0;
            for (int j = 0; j < nz; j++) gp += (double)y[j] * (double)gz[j];
            H.AssertLE(Fail, 5, gp, 0.0);      // regularized system is PD, so y is a descent direction

            snap.Dispose(); y.Dispose(); gz.Dispose();
            red.Dispose(); s.Dispose();
            Q.Dispose(); A.Dispose();
        }
    }

    // ================================================================================================
    // A/B equivalence of the two reduced-space paths: qpActiveSetCore with useIncrementalReduced
    // true vs false must agree on status, objective, and (strictly convex -> unique minimizer) x --
    // values, not iteration paths. Instance 1 starts at a fully tight corner (drop-heavy); instance 2
    // pushes against the upper box and a general row (mixed adds/drops).
    // ================================================================================================
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct FallbackEquivalenceJob : IJob
    {
        public NativeArray<double> Fail;

        void SolveBoth(in doubleMxN Q, in doubleN c, in doubleMxN A, in doubleN b,
                       NativeArray<ConstraintSense> senses, in doubleN xl, in doubleN xu,
                       int baseId, double tol)
        {
            int n = Q.M_Rows;
            var xInc = new doubleN(n, Allocator.Temp);   // zero-init: x0 = 0 (feasible by construction)
            var xBat = new doubleN(n, Allocator.Temp);

            var infoInc = QP.qpActiveSetCore(in Q, in c, in A, in b, senses, in xl, in xu, ref xInc, out double objInc, 0, true);
            var infoBat = QP.qpActiveSetCore(in Q, in c, in A, in b, senses, in xl, in xu, ref xBat, out double objBat, 0, false);

            H.AssertTrue(Fail, baseId + 0, infoInc.status == QPStatus.Optimal);
            H.AssertTrue(Fail, baseId + 1, infoBat.status == QPStatus.Optimal);
            H.AssertLE(Fail, baseId + 2, math.abs(objInc - objBat), tol);
            double devX = 0;
            for (int i = 0; i < n; i++) devX = math.max(devX, math.abs((double)(xInc[i] - xBat[i])));
            H.AssertLE(Fail, baseId + 3, devX, tol);

            xBat.Dispose(); xInc.Dispose();
        }

        public void Execute()
        {
            double tol = 1e-8;

            {   // instance 1: n = 8, corner start, interior-leaning optimum
                const int n = 8, m = 2;
                var Q = new doubleMxN(n, n, Allocator.Temp);
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++) Q[i, j] = i == j ? (double)3 : (double)0.25;
                var c = new doubleN(n, Allocator.Temp, false);
                for (int i = 0; i < n; i++) c[i] = (double)(-1.0 - 0.1 * i);
                var A = new doubleMxN(m, n, Allocator.Temp);
                for (int j = 0; j < n; j++) { A[0, j] = 1f; if ((j & 1) == 0) A[1, j] = 1f; }
                var b = new doubleN(m, Allocator.Temp, false);
                b[0] = (double)2.5; b[1] = (double)1.2;
                var senses = new NativeArray<ConstraintSense>(m, Allocator.Temp);
                for (int i = 0; i < m; i++) senses[i] = ConstraintSense.LessEqual;   // (default enum is Equal)
                var xl = new doubleN(n, Allocator.Temp);                            // 0
                var xu = new doubleN(n, Allocator.Temp, false);
                for (int i = 0; i < n; i++) xu[i] = (double)2;

                SolveBoth(in Q, in c, in A, in b, senses, in xl, in xu, 10, tol);

                xu.Dispose(); xl.Dispose(); senses.Dispose(); b.Dispose(); A.Dispose(); c.Dispose(); Q.Dispose();
            }

            {   // instance 2: n = 10, steep costs against the upper box + a tight sum row
                const int n = 10, m = 2;
                var Q = new doubleMxN(n, n, Allocator.Temp);
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++) Q[i, j] = i == j ? (double)2 : (double)0.1;
                var c = new doubleN(n, Allocator.Temp, false);
                for (int i = 0; i < n; i++) c[i] = (double)(-4.0 + 0.3 * i);
                var A = new doubleMxN(m, n, Allocator.Temp);
                for (int j = 0; j < n; j++) { A[0, j] = 1f; A[1, j] = (double)(0.2 * (j + 1)); }
                var b = new doubleN(m, Allocator.Temp, false);
                b[0] = (double)4; b[1] = (double)6;
                var senses = new NativeArray<ConstraintSense>(m, Allocator.Temp);
                for (int i = 0; i < m; i++) senses[i] = ConstraintSense.LessEqual;   // (default enum is Equal)
                var xl = new doubleN(n, Allocator.Temp);                            // 0
                var xu = new doubleN(n, Allocator.Temp, false);
                for (int i = 0; i < n; i++) xu[i] = (double)1;

                SolveBoth(in Q, in c, in A, in b, senses, in xl, in xu, 20, tol);

                xu.Dispose(); xl.Dispose(); senses.Dispose(); b.Dispose(); A.Dispose(); c.Dispose(); Q.Dispose();
            }
        }
    }

    [Test] public void UpDownDate() => H.Run(fail => new UpDownDateJob { Fail = fail }.Run());
    [Test] public void DependentAdd() => H.Run(fail => new DependentAddJob { Fail = fail }.Run());
    [Test] public void CornerToInterior() => H.Run(fail => new CornerToInteriorJob { Fail = fail }.Run());
    [Test] public void IncrementalReduced() => H.Run(fail => new IncrementalReducedJob { Fail = fail }.Run());
    [Test] public void CachedRetry() => H.Run(fail => new CachedRetryJob { Fail = fail }.Run());
    [Test] public void FallbackEquivalence() => H.Run(fail => new FallbackEquivalenceJob { Fail = fail }.Run());

    // ---- shared test-side helpers (Fail[]-array Burst diagnostic pattern, see QPEqpTests.double.cs) ----
    static class H
    {
        public static void AssertTrue(NativeArray<double> fail, int id, bool cond)
        {
            if (!cond && fail[0] == 0) { fail[0] = 1; fail[1] = id; fail[2] = 0; fail[3] = 1; fail[4] = 0; }
            Assert.IsTrue(cond);
        }
        public static void AssertLE(NativeArray<double> fail, int id, double val, double limit)
        {
            bool ok = val <= limit;
            if (!ok && fail[0] == 0) { fail[0] = 1; fail[1] = id; fail[2] = val; fail[3] = limit; fail[4] = val - limit; }
            Assert.IsTrue(ok);
        }

        public static void Run(Action<NativeArray<double>> runJob)
        {
            var fail = new NativeArray<double>(5, Allocator.TempJob);
            try
            {
                runJob(fail);
                if (fail[0] != 0)
                    Assert.Fail($"check {fail[1]}: got {fail[2]:G6}, limit/expected {fail[3]:G6}, diff {fail[4]:G6}");
            }
            finally { fail.Dispose(); }
        }
    }
}
